"use client"

/**
 * Bandeja de conversaciones.
 * Fuente: concepto visual de Divan Raj (@desdivj),
 * https://x.com/desdivj/status/2119738295039250507
 * Licencia: sin licencia, clean-room. No se copiaron assets, logos,
 * ilustraciones ni textos.
 * Compone el riel, el encabezado, la lista, el hilo y la ficha.
 * El canal, la etapa y la ventana llegan por props. Nada se envía solo.
 */

import { useEffect, useRef, useState } from "react"

import { cn } from "@/lib/utils"
import type { ConversationItemData, ConversationSection, PartyPanelData, SuggestionItem, ThreadFilter, ThreadMessageData, ThreadStatus } from "@/lib/thread-desk"
import { AppRail, type AppRailItem } from "@/components/ui/app-rail"
import { ChatThread } from "@/components/ui/chat-thread"
import { ConversationList } from "@/components/ui/conversation-list"
import { InboxPageHeader, type InboxCrumb, type InboxHeaderAction } from "@/components/ui/inbox-page-header"
import { PartyPanel } from "@/components/ui/party-panel"
import { SuggestedReplies } from "@/components/ui/suggested-replies"
import { ThreadComposer, type ComposerLock } from "@/components/ui/thread-composer"

export type InboxLayout = "auto" | "wide" | "desk" | "tablet" | "phone"

export type InboxCrmProps = {
  layout?: InboxLayout
  railLabel?: string
  railMark?: string
  railItems?: readonly AppRailItem[]
  onRail?: (id: string) => void
  crumbs?: readonly InboxCrumb[]
  title?: string
  subtitle?: string
  actions?: readonly InboxHeaderAction[]
  bellLabel?: string
  bellCount?: number
  onBell?: () => void
  listLabel?: string
  listTitle?: string
  countLabel?: string
  searchLabel?: string
  shortcut?: string
  filters?: readonly ThreadFilter[]
  filter?: string
  onFilterChange?: (value: string) => void
  sections?: readonly ConversationSection[]
  conversations?: readonly ConversationItemData[]
  selectedId?: string | null
  onSelect?: (id: string) => void
  threadLabel?: string
  threadTitle?: string
  threadStatus?: string
  threadPresence?: "online" | "offline" | "away"
  messages?: readonly ThreadMessageData[]
  typing?: { names: readonly string[]; label?: string }
  suggestions?: readonly SuggestionItem[]
  onSuggestion?: (id: string) => void
  onSend?: (value: string) => void
  onAsk?: () => void
  onAttach?: (files: File[]) => void
  onUseTemplate?: () => void
  locked?: ComposerLock | null
  party?: PartyPanelData
  onReveal?: (id: string) => void
  revealLabel?: string
  status?: ThreadStatus
  emptyLabel?: string
  loadingLabel?: string
  error?: string
  offlineLabel?: string
  onRetry?: () => void
  onRetryMessage?: (id: string) => void
  retryLabel?: string
  backLabel?: string
  contextLabel?: string
  initialColumn?: "list" | "thread"
  sendLabel?: string
  askLabel?: string
  attachLabel?: string
  placeholder?: string
  className?: string
}

function useAutoLayout(forced: InboxLayout) {
  const [layout, setLayout] = useState<Exclude<InboxLayout, "auto">>(forced === "auto" ? "wide" : forced)
  useEffect(() => {
    if (forced !== "auto") {
      setLayout(forced)
      return
    }
    const phone = window.matchMedia("(max-width: 639px)")
    const tablet = window.matchMedia("(max-width: 1023px)")
    const desk = window.matchMedia("(max-width: 1279px)")
    const read = () => {
      if (phone.matches) setLayout("phone")
      else if (tablet.matches) setLayout("tablet")
      else if (desk.matches) setLayout("desk")
      else setLayout("wide")
    }
    read()
    phone.addEventListener("change", read)
    tablet.addEventListener("change", read)
    desk.addEventListener("change", read)
    return () => {
      phone.removeEventListener("change", read)
      tablet.removeEventListener("change", read)
      desk.removeEventListener("change", read)
    }
  }, [forced])
  return layout
}

export function InboxCrm({
  layout: layoutProp = "auto",
  railLabel = "Espacios",
  railMark,
  railItems = [],
  onRail,
  crumbs = [],
  title = "Mensajes",
  subtitle,
  actions = [],
  bellLabel,
  bellCount,
  onBell,
  listLabel = "Conversaciones",
  listTitle = "Mensajes",
  countLabel,
  searchLabel = "Buscar mensajes",
  shortcut = "⌘K",
  filters,
  filter,
  onFilterChange,
  sections,
  conversations = [],
  selectedId,
  onSelect,
  threadLabel = "Hilo",
  threadTitle,
  threadStatus,
  threadPresence,
  messages = [],
  typing,
  suggestions = [],
  onSuggestion,
  onSend,
  onAsk,
  onAttach,
  onUseTemplate,
  locked = null,
  party,
  onReveal,
  revealLabel = "Mostrar",
  status = "ready",
  emptyLabel = "No hay conversaciones",
  loadingLabel = "Cargando la bandeja",
  error,
  offlineLabel = "Sin conexión",
  onRetry,
  onRetryMessage,
  retryLabel = "Reintentar",
  backLabel = "Volver",
  contextLabel = "Contexto",
  initialColumn = "list",
  sendLabel = "Enviar",
  askLabel = "Preguntar a IA",
  attachLabel = "Adjuntar",
  placeholder,
  className,
}: InboxCrmProps) {
  const rootRef = useRef<HTMLDivElement>(null)
  const layout = useAutoLayout(layoutProp)
  const [column, setColumn] = useState<"list" | "thread" | "context">(initialColumn)
  const [drawer, setDrawer] = useState(false)
  const [draft, setDraft] = useState("")
  const showRail = layout === "wide" || layout === "desk"
  const showList = layout !== "phone" || column === "list"
  const showThread = layout !== "phone" || column === "thread" || column === "context"
  const showParty = layout === "wide"

  useEffect(() => {
    function onKey(event: KeyboardEvent) {
      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") {
        event.preventDefault()
        rootRef.current?.querySelector<HTMLElement>("[data-slot=conversation-search]")?.focus()
      }
      if (event.key === "Escape") setDrawer(false)
    }
    window.addEventListener("keydown", onKey)
    return () => window.removeEventListener("keydown", onKey)
  }, [])

  function approve(id: string) {
    const item = suggestions.find((suggestion) => suggestion.id === id)
    if (item) setDraft(item.label)
    onSuggestion?.(id)
  }

  return (
    <div
      ref={rootRef}
      data-slot="inbox-crm"
      data-layout={layout}
      aria-busy={status === "loading" ? true : undefined}
      className={cn("flex min-h-[32rem] overflow-hidden rounded-2xl border border-border bg-background text-foreground", className)}
    >
      {showRail ? <AppRail label={railLabel} mark={railMark} items={railItems} onSelect={onRail} /> : null}
      <div className="flex min-w-0 flex-1 flex-col gap-4 p-4">
        <InboxPageHeader crumbs={crumbs} title={title} subtitle={subtitle} actions={actions} bellLabel={bellLabel} bellCount={bellCount} onBell={onBell} />
        {status === "loading" ? (
          <div role="status" aria-label={loadingLabel} className="grid flex-1 gap-3">
            <span className="sr-only">{loadingLabel}</span>
            <span className="h-24 animate-pulse rounded-2xl bg-muted" />
            <span className="h-40 animate-pulse rounded-2xl bg-muted" />
          </div>
        ) : null}
        {status === "error" ? (
          <div role="alert" className="grid gap-3 rounded-2xl border border-border p-4">
            <p className="text-sm text-destructive">{error}</p>
            {onRetry ? (
              <button type="button" className="h-11 justify-self-start rounded-full bg-foreground px-4 text-sm text-background" onClick={onRetry}>
                {retryLabel}
              </button>
            ) : null}
          </div>
        ) : null}
        {status !== "loading" && status !== "error" ? (
          <div className={cn("grid min-h-0 flex-1 gap-4", showParty ? "xl:grid-cols-[18rem_minmax(0,1fr)_18rem]" : "md:grid-cols-[18rem_minmax(0,1fr)]")}>
            {showList ? (
              <ConversationList
                label={listLabel}
                title={listTitle}
                countLabel={countLabel}
                searchLabel={searchLabel}
                shortcut={shortcut}
                filters={filters}
                filter={filter}
                onFilterChange={onFilterChange}
                sections={sections}
                items={conversations}
                selectedId={selectedId}
                status={status === "empty" ? "empty" : "ready"}
                emptyTitle={emptyLabel}
                onSelect={(id) => {
                  onSelect?.(id)
                  setColumn("thread")
                }}
              />
            ) : null}
            {showThread ? (
              <div className="flex min-h-0 min-w-0 flex-col gap-3">
                <div className="flex items-center gap-2">
                  {layout === "phone" ? (
                    <button type="button" className="h-11 rounded-full px-3 text-sm font-medium hover:bg-muted" onClick={() => setColumn("list")}>
                      {backLabel}
                    </button>
                  ) : null}
                  {!showParty ? (
                    <button type="button" className="ms-auto h-11 rounded-full px-3 text-sm font-medium hover:bg-muted" onClick={() => setDrawer(true)}>
                      {contextLabel}
                    </button>
                  ) : null}
                </div>
                {status === "offline" ? (
                  <p role="status" className="rounded-xl bg-muted px-3 py-2 text-sm text-foreground">
                    {offlineLabel}
                  </p>
                ) : null}
                <ChatThread
                  label={threadLabel}
                  title={threadTitle}
                  status={threadStatus}
                  presence={threadPresence}
                  messages={messages}
                  typing={typing}
                  onRetryMessage={onRetryMessage}
                  retryLabel={retryLabel}
                  state={status === "empty" ? "empty" : "ready"}
                  emptyLabel={emptyLabel}
                />
                {suggestions.length && !locked ? <SuggestedReplies items={suggestions} onApprove={approve} /> : null}
                <ThreadComposer
                  value={draft}
                  onValueChange={setDraft}
                  onSend={(value) => {
                    onSend?.(value)
                    setDraft("")
                  }}
                  onAsk={onAsk}
                  onAttach={onAttach}
                  onUseTemplate={onUseTemplate}
                  locked={locked}
                  offline={status === "offline"}
                  placeholder={placeholder}
                  sendLabel={sendLabel}
                  askLabel={askLabel}
                  attachLabel={attachLabel}
                />
              </div>
            ) : null}
            {showParty && party ? (
              <div className="min-w-0 border-s border-border ps-4">
                <PartyPanel {...party} revealLabel={revealLabel} onReveal={onReveal} />
              </div>
            ) : null}
          </div>
        ) : null}
      </div>
      {drawer && party ? (
        <div role="dialog" aria-label={contextLabel} className="fixed inset-y-0 end-0 z-40 flex w-80 max-w-full flex-col border-s border-border bg-popover p-4 shadow-none">
          <button type="button" className="mb-3 h-11 self-end rounded-full px-3 text-sm" onClick={() => setDrawer(false)}>
            {backLabel}
          </button>
          <PartyPanel {...party} revealLabel={revealLabel} onReveal={onReveal} />
        </div>
      ) : null}
    </div>
  )
}

/**
 * Bandeja de conversaciones.
 * Fuente: concepto visual de Divan Raj (@desdivj),
 * https://x.com/desdivj/status/2119738295039250507
 * Licencia: sin licencia, clean-room. No se copiaron assets, logos,
 * ilustraciones ni textos.
 * Tipos y puertos. Sin red, sin Supabase y sin dominio de un canal.
 */

import type { ReactNode } from "react"

import { foldInboxText, type DeskPresence } from "@/lib/inbox"

export type ThreadStatus = "ready" | "loading" | "empty" | "error" | "offline"

export type ThreadFilter = {
  value: string
  label: string
}

export type ConversationSection = {
  id: string
  label: string
  hint?: string
}

export type ConversationItemData = {
  id: string
  title: string
  preview?: string
  time?: string
  unread?: number
  section?: string
  tags?: readonly string[]
  presence?: DeskPresence
  role?: string
  kind?: "thread" | "contact"
  stage?: string
  windowLabel?: string
  channel?: ReactNode
}

export type DeliveryState = "sending" | "sent" | "delivered" | "read" | "failed"

export type ThreadNote = {
  title: string
  detail: string
  body?: string
}

export type ThreadFile = {
  name: string
  detail: string
  status?: string
}

export type ThreadInvoice = {
  title: string
  amount: string
  due: string
}

export type ThreadMetric = {
  title: string
  chip?: string
  value: string
  caption?: string
  filled: number
  total: number
  start: string
  end: string
}

export type ThreadMessageData = {
  id: string
  side: "incoming" | "outgoing"
  author: string
  time?: string
  body?: string
  delivery?: DeliveryState
  deliveryLabel?: string
  grouped?: "single" | "start" | "middle" | "end"
  enter?: boolean
  note?: ThreadNote
  file?: ThreadFile
  invoice?: ThreadInvoice
  metric?: ThreadMetric
}

export type SuggestionItem = {
  id: string
  label: string
}

export type SecretField = {
  id: string
  label: string
  masked: string
  revealed: string
}

export type PartyFact = {
  id: string
  label: string
  value: string
}

export type PartyMember = {
  id: string
  name: string
  role: string
}

export type PartyFile = {
  id: string
  name: string
  detail: string
}

export type PartyDeal = {
  title: string
  status: string
  amount: string
  value: number
  label: string
}

export type PartyPanelData = {
  name: string
  meta?: string
  deal?: PartyDeal
  facts?: readonly PartyFact[]
  members?: readonly PartyMember[]
  files?: readonly PartyFile[]
  secrets?: readonly SecretField[]
}

export function matchesConversation(item: ConversationItemData, filter: string | undefined, query: string) {
  if (filter && filter !== "all") {
    const tagged = item.tags?.includes(filter) || (filter === "unread" && (item.unread ?? 0) > 0)
    if (!tagged) return false
  }
  const needle = query.trim()
  if (!needle) return true
  const hay = [item.title, item.preview, item.role, item.stage, item.windowLabel].filter(Boolean).join(" ")
  return foldInboxText(hay).includes(foldInboxText(needle))
}

export function groupMessages(messages: readonly ThreadMessageData[]): ThreadMessageData[] {
  return messages.map((message, index) => {
    if (message.grouped) return message
    const prev = messages[index - 1]
    const next = messages[index + 1]
    const same = (other?: ThreadMessageData) =>
      Boolean(other && other.side === message.side && other.author === message.author && !other.file && !other.invoice && !other.metric && !message.file && !message.invoice && !message.metric)
    const before = same(prev)
    const after = same(next)
    const grouped = before && after ? "middle" : before ? "end" : after ? "start" : "single"
    return { ...message, grouped }
  })
}

/**
 * Shared types for the desk pieces. No fetching, no theme.
 * Dates are calendar days (`YYYY-MM-DD`). The host owns locale and timezone.
 */

export const DESK_PRESENCES = ["online", "offline", "away"] as const

export type DeskPresence = (typeof DESK_PRESENCES)[number]

export type DeskMessage = {
  id: string
  author: string
  body: string
  /** Preformatted time. */
  time: string
  side: "incoming" | "outgoing"
  note?: boolean
  receipt?: "seen" | "unseen"
}

export type DeskOption = {
  value: string
  label: string
}

const DATE_RE = /^(\d{4})-(\d{2})-(\d{2})$/

export function foldInboxText(value: string): string {
  return value.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase()
}

export function isCalendarDate(value: string | undefined): value is string {
  return Boolean(value && DATE_RE.test(value))
}

/** True when `due` is a calendar day before `today`. */
export function isOverdueDate(due: string | undefined, today: string): boolean {
  if (!isCalendarDate(due) || !isCalendarDate(today)) return false
  return due < today
}

export function formatDeskDate(iso: string, locale?: string): string {
  if (!isCalendarDate(iso)) return iso
  const [year, month, day] = iso.split("-").map(Number)
  return new Intl.DateTimeFormat(locale, { dateStyle: "medium", timeZone: "UTC" }).format(
    new Date(Date.UTC(year, month - 1, day)),
  )
}

export function deskInitials(name: string): string {
  const letters = name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase() ?? "")
    .join("")
  return letters || "?"
}
